cd /testbed && /opt/miniconda3/envs/testbed/bin/python - <<'PYEOF'
p = "xarray/core/computation.py"
s = open(p).read()

start = s.index('    """\n    if keep_attrs is None:')
end = s.index('\ndef polyval(')

NEW = '''    """
    if keep_attrs is None:
        keep_attrs = _get_keep_attrs(default=False)

    if isinstance(keep_attrs, bool):
        keep_attrs = "override" if keep_attrs else "drop"

    # alignment for three arguments is complicated, so don't support it yet
    result = apply_ufunc(
        duck_array_ops.where,
        cond,
        x,
        y,
        join="exact",
        dataset_join="exact",
        dask="allowed",
        keep_attrs=keep_attrs,
    )

    if keep_attrs == "drop":
        return result

    # ``apply_ufunc`` combines the attributes of the first object of each type,
    # which is usually ``cond``: a boolean mask that rarely carries attributes.
    # Fall back to the attributes of the values (``x`` and ``y``) whenever the
    # combined attributes are empty, so that ``keep_attrs=True`` preserves them.
    if hasattr(result, "data_vars"):
        targets = [(None, result)] + [(name, result[name]) for name in result.data_vars]
    elif hasattr(result, "attrs"):
        targets = [(None, result)]
    else:
        return result

    for name, target in targets:
        if target.attrs:
            continue
        candidates = [
            attrs
            for attrs in (_where_get_attrs(obj, name=name) for obj in (x, y, cond))
            if attrs
        ]
        if candidates:
            target.attrs = merge_attrs(candidates, combine_attrs=keep_attrs) or {}

    return result


def _where_get_attrs(obj, name=None):
    """Return the attributes of ``obj``, optionally of one of its data variables."""
    if name is not None:
        data_vars = getattr(obj, "data_vars", None)
        if data_vars is None or name not in data_vars:
            return None
        obj = data_vars[name]
    return getattr(obj, "attrs", None)
'''

s = s[:start] + NEW + s[end:]
open(p, "w").write(s)
print("patched")
